{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Dapagliflozin, which shares the identical aglycone and differs mainly in the sugar ring, has an absolute oral bioavailability of 78% (90% CI 73–83%) in healthy volunteers, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Bexagliflozin, a closely related SGLT2 inhibitor, has an absolute oral bioavailability of about 78% in humans, supporting high oral bioavailability for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Empagliflozin, another SGLT2 inhibitor with a similar C-aryl glycoside structure, has an absolute oral bioavailability of 90% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Tofogliflozin, which contains a rigid bicyclic sugar moiety, has an absolute oral bioavailability of about 98% in healthy subjects, indicating that cyclic sugar modifications do not abolish high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a dapagliflozin analog with a 3,6-anhydro sugar modification. Direct absolute bioavailability data for dapagliflozin (78%) and other closely related SGLT2 inhibitors (bexagliflozin ~78%, empagliflozin 90%, tofogliflozin ~97.5%) all exceed the 20% threshold. The structural modification is unlikely to reduce F below 20%, so the prediction is high.",
  "evidence_gaps": [
    "No direct bioavailability measurement for the exact query molecule.",
    "The effect of the 3,6-anhydro bridge on intestinal absorption and first-pass metabolism is not directly measured.",
    "All evidence is from related SGLT2 inhibitors rather than the query itself."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

